class Solution:
    def calculateScore(self, s: str) -> int:
        score = 0
        positions = [[] for _ in range(26)]

        for i, char in enumerate(s):
            idx = ord(char) - ord('a')
            mirror_idx = 25 - idx

            if positions[mirror_idx]:
                j = positions[mirror_idx].pop()
                score += i - j
            else:
                positions[idx].append(i)

        return score
